import java.util.List;

public class DiscountEngine {
    public double calculateRebate(List<Double> cartAmounts) {
        double sum = 0.0;
        for (Double amt : cartAmounts) {
            sum += amt;
        }
        return sum > 100.0 ? sum * 0.1 : 0.0;
    }
}

